package com.example.InvestIQ.controller;

import com.example.InvestIQ.entity.StockQuote;
import com.example.InvestIQ.service.MarketDataService;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/market-data")
public class MarketDataController {

	private final MarketDataService marketDataService;

	public MarketDataController(MarketDataService marketDataService) {
		this.marketDataService = marketDataService;
	}

	@GetMapping("/stocks/{symbol}")
	public StockQuote getStockQuote(@PathVariable String symbol) {
		return marketDataService.fetchStockQuote(symbol);
	}

}

package com.example.InvestIQ.repository;

import com.example.InvestIQ.entity.StockQuote;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

@Repository
public class StockQuoteRepository {
    private final JdbcTemplate jdbcTemplate;

    private final RowMapper<StockQuote> rowMapper = (rs, rowNum) -> {
        StockQuote quote = new StockQuote();
        quote.setId(rs.getLong("id"));
        quote.setSymbol(rs.getString("symbol"));
        quote.setCompanyName(rs.getString("company_name"));
        quote.setCurrentPrice(rs.getBigDecimal("current_price"));
        quote.setPriceChange(rs.getBigDecimal("price_change"));
        quote.setPercentChange(rs.getBigDecimal("percent_change"));
        quote.setPreviousClose(rs.getBigDecimal("previous_close"));
        quote.setDayHigh(rs.getBigDecimal("day_high"));
        quote.setDayLow(rs.getBigDecimal("day_low"));
        Timestamp lastUpdated = rs.getTimestamp("last_updated");
        quote.setLastUpdated(lastUpdated != null ? lastUpdated.toLocalDateTime() : null);
        return quote;
    };

    public StockQuoteRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public List<StockQuote> findAll() {
        return jdbcTemplate.query("SELECT * FROM stock_quotes ORDER BY id", rowMapper);
    }

    public Optional<StockQuote> findById(Long id) {
        return jdbcTemplate.query("SELECT * FROM stock_quotes WHERE id = ?", rowMapper, id)
                .stream()
                .findFirst();
    }

    public Optional<StockQuote> findBySymbol(String symbol) {
        return jdbcTemplate.query("SELECT * FROM stock_quotes WHERE symbol = ?", rowMapper, symbol)
                .stream()
                .findFirst();
    }
}

package com.example.InvestIQ.repository;

import com.example.InvestIQ.entity.StockQuote;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.sql.Timestamp;
import java.util.List;
import java.util.Optional;

@Repository
public class StockQuoteRepository {
    private final JdbcTemplate jdbcTemplate;

    private final RowMapper<StockQuote> rowMapper = (rs, rowNum) -> {
        StockQuote quote = new StockQuote();
        quote.setId(rs.getLong("id"));
        quote.setSymbol(rs.getString("symbol"));
        quote.setCompanyName(rs.getString("company_name"));
        quote.setCurrentPrice(rs.getBigDecimal("current_price"));
        quote.setPriceChange(rs.getBigDecimal("price_change"));
        quote.setPercentChange(rs.getBigDecimal("percent_change"));
        quote.setPreviousClose(rs.getBigDecimal("previous_close"));
        quote.setDayHigh(rs.getBigDecimal("day_high"));
        quote.setDayLow(rs.getBigDecimal("day_low"));
        Timestamp lastUpdated = rs.getTimestamp("last_updated");
        quote.setLastUpdated(lastUpdated != null ? lastUpdated.toLocalDateTime() : null);
        return quote;
    };

    public StockQuoteRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public List<StockQuote> findAll() {
        return jdbcTemplate.query("SELECT * FROM stock_quotes ORDER BY id", rowMapper);
    }

    public Optional<StockQuote> findById(Long id) {
        return jdbcTemplate.query("SELECT * FROM stock_quotes WHERE id = ?", rowMapper, id)
                .stream()
                .findFirst();
    }

    public Optional<StockQuote> findBySymbol(String symbol) {
        return jdbcTemplate.query("SELECT * FROM stock_quotes WHERE symbol = ?", rowMapper, symbol)
                .stream()
                .findFirst();
    }

    public StockQuote saveOrUpdate(StockQuote quote) {
        Optional<StockQuote> existing = findBySymbol(quote.getSymbol());

        if (existing.isPresent()) {
            jdbcTemplate.update(
                    "UPDATE stock_quotes SET company_name = ?, current_price = ?, price_change = ?, percent_change = ?, previous_close = ?, day_high = ?, day_low = ?, last_updated = CURRENT_TIMESTAMP WHERE symbol = ?",
                    quote.getCompanyName(),
                    quote.getCurrentPrice(),
                    quote.getPriceChange(),
                    quote.getPercentChange(),
                    quote.getPreviousClose(),
                    quote.getDayHigh(),
                    quote.getDayLow(),
                    quote.getSymbol()
            );
        } else {
            jdbcTemplate.update(
                    "INSERT INTO stock_quotes (symbol, company_name, current_price, price_change, percent_change, previous_close, day_high, day_low) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    quote.getSymbol(),
                    quote.getCompanyName(),
                    quote.getCurrentPrice(),
                    quote.getPriceChange(),
                    quote.getPercentChange(),
                    quote.getPreviousClose(),
                    quote.getDayHigh(),
                    quote.getDayLow()
            );
        }

        return findBySymbol(quote.getSymbol()).orElse(quote);
    }
}

package com.example.InvestIQ.service;

import org.springframework.stereotype.Service;

@Service
public class MarketDataService {
}

package com.example.InvestIQ.service;

import com.example.InvestIQ.entity.StockQuote;
import com.example.InvestIQ.repository.StockQuoteRepository;
import com.fasterxml.jackson.databind.JsonNode;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.stereotype.Service;
import org.springframework.util.StringUtils;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.server.ResponseStatusException;

import java.math.BigDecimal;
import java.time.Duration;
import java.time.LocalDateTime;

import static org.springframework.http.HttpStatus.BAD_GATEWAY;
import static org.springframework.http.HttpStatus.BAD_REQUEST;
import static org.springframework.http.HttpStatus.NOT_FOUND;
import static org.springframework.http.HttpStatus.SERVICE_UNAVAILABLE;

@Service
public class MarketDataService {

	private final RestTemplate restTemplate;
	private final StockQuoteRepository stockQuoteRepository;
	private final String stockApiBaseUrl;
	private final String stockApiKey;

	public MarketDataService(
			RestTemplateBuilder restTemplateBuilder,
			StockQuoteRepository stockQuoteRepository,
			@Value("${stock.api.base-url:https://www.alphavantage.co/query}") String stockApiBaseUrl,
			@Value("${stock.api.key:demo}") String stockApiKey,
			@Value("${stock.api.timeout-ms:5000}") long timeoutMs) {
		this(
				restTemplateBuilder
						.setConnectTimeout(Duration.ofMillis(timeoutMs))
						.setReadTimeout(Duration.ofMillis(timeoutMs))
						.build(),
				stockQuoteRepository,
				stockApiBaseUrl,
				stockApiKey
		);
	}

	MarketDataService(
			RestTemplate restTemplate,
			StockQuoteRepository stockQuoteRepository,
			String stockApiBaseUrl,
			String stockApiKey) {
		this.restTemplate = restTemplate;
		this.stockQuoteRepository = stockQuoteRepository;
		this.stockApiBaseUrl = stockApiBaseUrl;
		this.stockApiKey = stockApiKey;
	}

	public StockQuote fetchStockQuote(String symbol) {
		String normalizedSymbol = normalizeSymbol(symbol);

		if (!StringUtils.hasText(stockApiKey)) {
			throw new ResponseStatusException(SERVICE_UNAVAILABLE, "Stock API key is not configured");
		}

		String requestUrl = String.format(
				"%s?function=GLOBAL_QUOTE&symbol=%s&apikey=%s",
				stockApiBaseUrl,
				normalizedSymbol,
				stockApiKey
		);

		JsonNode response;
		try {
			response = restTemplate.getForObject(requestUrl, JsonNode.class);
		} catch (RestClientException ex) {
			throw new ResponseStatusException(BAD_GATEWAY, "Failed to fetch stock data from external API", ex);
		}

		if (response == null) {
			throw new ResponseStatusException(BAD_GATEWAY, "Stock API returned an empty response");
		}

		JsonNode globalQuote = response.path("Global Quote");
		if (globalQuote.isMissingNode() || globalQuote.isEmpty()) {
			String providerMessage = extractProviderMessage(response);
			if (providerMessage != null) {
				throw new ResponseStatusException(BAD_GATEWAY, providerMessage);
			}
			throw new ResponseStatusException(NOT_FOUND, "No stock data found for symbol " + normalizedSymbol);
		}

		StockQuote quote = new StockQuote();
		quote.setSymbol(normalizedSymbol);
		quote.setCompanyName(normalizedSymbol);
		quote.setCurrentPrice(parseDecimal(globalQuote, "05. price"));
		quote.setPriceChange(parseDecimal(globalQuote, "09. change"));
		quote.setPercentChange(parsePercent(globalQuote.path("10. change percent").asText(null)));
		quote.setPreviousClose(parseDecimal(globalQuote, "08. previous close"));
		quote.setDayHigh(parseDecimal(globalQuote, "03. high"));
		quote.setDayLow(parseDecimal(globalQuote, "04. low"));
		quote.setLastUpdated(LocalDateTime.now());

		if (quote.getCurrentPrice() == null) {
			throw new ResponseStatusException(NOT_FOUND, "No stock data found for symbol " + normalizedSymbol);
		}

		return stockQuoteRepository.saveOrUpdate(quote);
	}

	private String normalizeSymbol(String symbol) {
		String normalizedSymbol = symbol == null ? "" : symbol.trim().toUpperCase();
		if (!StringUtils.hasText(normalizedSymbol)) {
			throw new ResponseStatusException(BAD_REQUEST, "Stock symbol is required");
		}
		return normalizedSymbol;
	}

	private BigDecimal parseDecimal(JsonNode node, String fieldName) {
		String rawValue = node.path(fieldName).asText(null);
		if (!StringUtils.hasText(rawValue)) {
			return null;
		}
		try {
			return new BigDecimal(rawValue.trim());
		} catch (NumberFormatException ex) {
			throw new ResponseStatusException(BAD_GATEWAY, "Invalid numeric value returned by stock API for field " + fieldName, ex);
		}
	}

	private BigDecimal parsePercent(String rawValue) {
		if (!StringUtils.hasText(rawValue)) {
			return null;
		}
		String cleanedValue = rawValue.replace("%", "").trim();
		try {
			return new BigDecimal(cleanedValue);
		} catch (NumberFormatException ex) {
			throw new ResponseStatusException(BAD_GATEWAY, "Invalid percent value returned by stock API", ex);
		}
	}

	private String extractProviderMessage(JsonNode response) {
		String[] candidateFields = {"Note", "Information", "Error Message"};
		for (String candidateField : candidateFields) {
			String message = response.path(candidateField).asText(null);
			if (StringUtils.hasText(message)) {
				return message;
			}
		}
		return null;
	}
}
